#!/bin/bash
#
# Materialize every bundle under bundles/ as real files copied from the
# canonical skills/ and assets/ trees.
#
# Agent Plugins 1.0.0 (§4.1.3-4.1.4) rejects any symlink that resolves outside
# the plugin root, and each bundles/<name>/ is its own plugin root. A bundle
# built from symlinks back into skills/ therefore loads zero skills in a
# conforming client installing from a git checkout. So bundles hold copies,
# regenerated by this script and kept honest in CI by check-bundles.sh.
#
# skills/ and assets/ stay canonical. Never edit a file under bundles/*/skills/
# or bundles/*/assets/ by hand; edit the canonical copy and re-run this.
#
# Membership:
#   - Bundles listed in FULL_LIBRARY_BUNDLES carry every skill in skills/.
#   - Every other bundle carries exactly the skills named by the directories
#     already in bundles/<name>/skills/. To add a skill to a bundle, create
#     the empty directory bundles/<name>/skills/<skill> and re-run; to drop
#     one, delete that directory.
#
# Every bundle also gets assets/icon.png, the icon its manifests name.

set -euo pipefail

cd "$(dirname "$0")"

# Bundles that publish the whole library rather than a curation.
FULL_LIBRARY_BUNDLES=(britts-agent-skills)

ICON="assets/icon.png"

is_full_library() {
  local bundle=$1 b
  for b in "${FULL_LIBRARY_BUNDLES[@]}"; do
    [ "$b" = "$bundle" ] && return 0
  done
  return 1
}

# Replace dest with an exact copy of src (a directory), dropping anything
# stale. -p keeps the executable bit that git tracks.
copy_dir() {
  local src=$1 dest=$2
  rm -rf "$dest"
  cp -Rp "$src" "$dest"
}

status=0

for bundle_dir in bundles/*/; do
  bundle=$(basename "$bundle_dir")
  skills_dir="bundles/$bundle/skills"

  # A whole-directory symlink (the old full-library layout) has to go before
  # anything is copied into it, or the copy would land in skills/ itself.
  [ -L "$skills_dir" ] && rm "$skills_dir"
  mkdir -p "$skills_dir"

  if is_full_library "$bundle"; then
    names=()
    for dir in skills/*/; do
      names+=("$(basename "$dir")")
    done
    # Drop skills that no longer exist in skills/.
    for entry in "$skills_dir"/*; do
      [ -e "$entry" ] || [ -L "$entry" ] || continue
      if [ ! -d "skills/$(basename "$entry")" ]; then
        rm -rf "$entry"
        echo "Removed stale $entry"
      fi
    done
  else
    names=()
    for entry in "$skills_dir"/*; do
      [ -e "$entry" ] || [ -L "$entry" ] || continue
      names+=("$(basename "$entry")")
    done
  fi

  for name in "${names[@]}"; do
    if [ ! -d "skills/$name" ]; then
      echo "error: $skills_dir/$name has no canonical skills/$name" >&2
      status=1
      continue
    fi
    copy_dir "skills/$name" "$skills_dir/$name"
  done

  mkdir -p "bundles/$bundle/assets"
  rm -f "bundles/$bundle/$ICON"
  cp -p "$ICON" "bundles/$bundle/$ICON"

  echo "Synced bundles/$bundle (${#names[@]} skills)"
done

exit "$status"
